//! 🧫️ Explicit shared native fixture for the two actual procedural persisted type pairs.
use semio_framework_artifact_flow_flow::{FlowHostSnapshot,Widget};
use semio_framework_artifact_playbook_playbook::{GenerationPlayRoot,GenerationPlayState};
use semio_framework_value::DslValue;
use semio_framework_value::FromValue;
use semio_framework_value::Number;
fn word(v:&serde_json::Value)->f64{f64::from_bits(u64::from_str_radix(v.as_str().unwrap(),16).unwrap())}
fn answer(v:&serde_json::Value)->DslValue{match v["kind"].as_str().unwrap(){"null"=>semio_framework_value::DslValue::Null,"boolean"=>semio_framework_value::DslValue::Bool(v["value"].as_bool().unwrap()),"unsigned"=>semio_framework_value::DslValue::Number(semio_framework_value::Number::UInt(v["value"].as_str().unwrap().parse().unwrap())),"integer"=>semio_framework_value::DslValue::Number(semio_framework_value::Number::Int(v["value"].as_str().unwrap().parse().unwrap())),"float"=>semio_framework_value::DslValue::Number(semio_framework_value::Number::Float(word(&v["bits"]))),"string"=>semio_framework_value::DslValue::String(v["value"].as_str().unwrap().into()),"bytes"=>{let s=v["hex"].as_str().unwrap();semio_framework_value::DslValue::Bytes(s.as_bytes().chunks_exact(2).map(|b|u8::from_str_radix(std::str::from_utf8(b).unwrap(),16).unwrap()).collect())},"array"=>semio_framework_value::DslValue::Array(v["values"].as_array().unwrap().iter().map(answer).collect()),"object"=>semio_framework_value::DslValue::Object(v["members"].as_array().unwrap().iter().map(|m|(m["key"].as_str().unwrap().into(),answer(&m["value"]))).collect()),_=>panic!("fixture intrinsic value kind")}}
/// 📸️ Constructs every declared owned field using its native type boundary, preserving exact scalar words.
pub fn fixture(source:&str)->(FlowHostSnapshot,GenerationPlayRoot){let mut f:serde_json::Value=serde_json::from_str(source).unwrap();let lower=f["integerWords"]["minimum"].as_str().unwrap().parse::<i64>().unwrap();let upper=f["integerWords"]["maximum"].as_str().unwrap().parse::<i64>().unwrap();f["hostSnapshot"]["widgets"][0]["params"]["int"]=serde_json::Value::from(lower);f["hostSnapshot"]["widgets"][8]["tree"]["neurons"][0]["tree"]["neurons"][0]["params"]["value"]=serde_json::Value::from(upper);let mut host=FlowHostSnapshot::from_value(f["hostSnapshot"].clone().into()).unwrap();let words=&f["words"];host.camera.x=word(&words[0]);host.camera.y=word(&words[1]);host.camera.zoom=word(&words[2]);for widget in &mut host.widgets{if let Widget::InputSlider{value,min,max,step,..}=widget{*value=word(&words[3]);*min=word(&words[4]);*max=word(&words[5]);*step=word(&words[6]);}}let mut generation=GenerationPlayState::from_value(f["generation"].clone().into()).unwrap();semio_framework_value::FromValue::retire_decoded(std::mem::take(&mut generation.generations[1].values));for a in f["answers"].as_array().unwrap(){generation.generations[1].values.insert(a["key"].as_str().unwrap().into(),answer(a));}(host,generation.into())}
